def _run_awaitable(value: Any) -> Any:
    """Resolve an awaitable without assuming an event loop is running.

    Real tools (``SearchEngineTool.search`` / ``BrowsingAgent.browse``) are
    coroutines while test doubles are frequently plain functions, so callers can
    pass either. When no loop is running we simply use ``asyncio.run``; if a loop
    is already running we execute the coroutine in a dedicated worker thread to
    avoid re-entrancy errors.
    """
    if not inspect.isawaitable(value):
        return value

    async def _await_it():
        return await value

    try:
        asyncio.get_running_loop()
    except RuntimeError:
        return asyncio.run(_await_it())

    box: Dict[str, Any] = {}

    def _worker():
        box["value"] = asyncio.run(_await_it())

    thread = threading.Thread(target=_worker)
    thread.start()
    thread.join()
    return box.get("value")


