def _gather_evidence(self, plan: Dict[str, Any]) -> Dict[str, Any]:
    """Acquire evidence for every sub-question in ``plan``.

    Runs :meth:`SearchEngineTool.search` once per sub-question, browses the
    top-K result URLs with :meth:`BrowsingAgent.browse` (using the plan's
    ``target_language``) and accumulates a URL-deduplicated evidence
    structure. The wall-clock budget ``max_research_time_s`` is enforced:
    once exceeded, gathering stops and ``evidence["truncated"]`` is ``True``.
    """
    subquestions = plan.get("subquestions") if isinstance(plan, dict) else None
    if not isinstance(subquestions, list):
        subquestions = []
    subquestions = [s for s in subquestions if isinstance(s, str) and s.strip()]

    language = plan.get("target_language") if isinstance(plan, dict) else None
    if language not in VALID_TARGET_LANGUAGES:
        language = self.detect_language(" ".join(subquestions))

    start_time = time.time()
    deadline = start_time + self.max_research_time_s

    items_by_url: Dict[str, Dict[str, Any]] = {}
    truncated = False
    search_calls = 0
    browse_calls = 0
    search_successes = 0
    opaque_searches = 0

    for subquestion in subquestions:
        if time.time() >= deadline:
            truncated = True
            break

        query = subquestion.strip()
        self._log_step("search", query)
        search_calls += 1

        raw_results = None
        if self.search_tool is not None:
            try:
                raw_results = _run_awaitable(self.search_tool.search(query))
            except Exception:
                raw_results = None

