def _render_evidence_block(id_to_item: Dict[str, Dict[str, Any]]) -> str:
    """Render evidence items into a compact, citation-labelled block."""
    lines: List[str] = []
    for sid, item in id_to_item.items():
        lines.append(f"[{sid}]")
        url = item.get("url")
        if isinstance(url, str) and url.strip():
            lines.append(f"url: {url.strip()}")
        title = item.get("title")
