def _sanitize_citations(answer: Any, valid_ids: set) -> str:
    """Normalise citations and drop any that do not map to real evidence."""
    if not isinstance(answer, str):
        return ""
    text = _expand_citation_groups(answer)

    def _replace(match: "re.Match[str]") -> str:
        sid = f"S{int(match.group(1))}"
        return f"[{sid}]" if sid in valid_ids else ""

    return _CITATION_RE.sub(_replace, text)

@staticmethod
def _extract_used_sources(answer: Any, valid_ids: set) -> List[str]:
    """Return the evidence ids referenced in ``answer`` (order preserved)."""
    used: List[str] = []
    seen = set()
    if not isinstance(answer, str):
        return used
    for match in _CITATION_RE.finditer(answer):
        sid = f"S{int(match.group(1))}"
        if sid in valid_ids and sid not in seen:
            seen.add(sid)
            used.append(sid)
